 "හේතු ධර්මයන් සමඟ ඒකෝත්පාදාදී ලක්ෂණ නැත්තාවූ ධර්මයෝ \"හෙතුවිප්පයුත්තා\" නම් වේ.": "缺乏与诸根法一同生起等特征的诸法，称为“根不相应”（hetuvippayuttā）。",
 "අහේතුක දුකයට සමාන අර්ථයක් ඇත.": "其义与无因（ahetuka）二法相似。",
 "ඡන්දය හැර චෛතසික 12.": "12 个心所，除欲。",
 "රූප, වේදනා, සඤ්ඤා, සංඛාර, විඤ්ඤාණ.": "色、受、想、行、识。",
 "දුක්ඛ, නිරෝධ.": "苦、灭。",
 "මෙම දුකයෙන් බැහැර වන ධර්ම නොමැත.": "没有被排除于此二法之外的法。",
 "හේතු ධර්මයන් සහ සහේතුක ධර්මයන් එකවර වන ධර්ම.": "既是根又是有因的诸法。",
 "හේතු නම් වූ ද සහේතුක වූ ද ධර්ම.": "既是根又是有因的诸法。",
 "මෝහ මූල දෙසිත්හි මෝහය හැර හේතු 6.": "6 个根，除两个痴根心中的痴。",
 "මෙම පදයට අයත් ධර්මයන් පහත පරිදි වේ.": "属于此术语的诸法如下。",
 "මෝහ මූල දෙසිත්හි මෝහය හැර ලෝභ, දෝස, අලෝභ, අදෝස, අමෝහ.": "贪、嗔、无贪、无嗔、无痴——除两个痴根心中的痴。",
 "සංග්‍රහය පහත පරිදි වේ.": "摄类（saṅgaha）如下。",
 "සංස්කාරස්කන්ධය.": "行蕴。",
