 "ෂඩ්ද්වාරයෙන් වැගිරෙන බැවින් ලෝභ, දිට්ඨි, මෝහ යන ධර්ම \"ආසව\" නම් වේ.": "因为经由六门流出，贪、见与痴诸法称为“漏”（āsava）。",
 "දෙවන ක්‍රමය - (භූමිතො ආභවග්ගං, ධම්මතො ආගොත්‍රභූං සවන්තී'ති = ආසවා). තෙවන ක්‍රමය - (චිරපාරිවාසියට්ඨෙන මදිරාදයො ආසවා වියා'ති = ආසවා). සතරවන ක්‍රමය - (ආයතිං සංසාරදුක්ඛං සවන්තී'ති = ආසවා).": "第二种方法——（bhūmito ābhavaggaṃ, dhammato āgotrabhuṃ savantī'ti = āsavā）。第三种方法——（cirapārivāsiyaṭṭhena madirādayo āsavā viyā'ti = āsavā）。第四种方法——（āyatiṃ saṃsāradukkhaṃ savantī'ti = āsavā）。",
 "කාමාශ්‍රවය හා භවාශ්‍රවය ලෝභ චෛතසිකය යි.": "欲漏（kāmāsava）与有漏（bhavāsava）是贪心所。",
 "දිට්ඨාශ්‍රවය දිට්ඨි චෛතසිකය යි.": "见漏（diṭṭhāsava）是见心所。",
 "අවිජ්ජාශ්‍රවය මෝහ චෛතසිකය යි.": "无明漏（avijjāsava）是痴心所。",
 "එකම සංස්කාරස්කන්ධයකි.": "它是单一的行蕴。",
 "එකම ධම්මායතනයකි.": "它是单一的法处。",
 "එකම ධම්මධාතුවකි.": "它是单一的法界。",
 "දිට්ඨි මෝහ දෙක දුක්ඛ සත්‍යයකි, ලෝභය සමුදය සත්‍යයකි.": "见与痴是苦谛；贪是集谛。",
 "ලෝභ, දිට්ඨි, මෝහ නම් වූ චෛතසික තිදෙනා ලැබෙන්නාහ.": "得到称为贪、见与痴的三个心所。",
 "ආසව චෛතසික 3": "3 个漏心所",
 "දිට්ඨි මෝහ දෙක": "见与痴",
 "ලෝභය": "贪",
 "ආශ්‍රව නම් නොවන්නා වූ ධර්ම ය.": "不称为漏的诸法。",
 "ආශ්‍රව ධර්ම තුන හැර සෙසු සියලු පරමාර්ථ ධර්ම මෙයට අයත් වේ.": "除三个漏法之外的其余一切究竟法，属于此。",
 "ආශ්‍රව ධර්ම තුන වර්ජිත චෛතසික 49.": "49 个心所，除三个漏法。",
 "දුක්ඛ, නිරෝධ, මාර්ග.": "苦、灭、道。",
 "එකුන් අනූ චිත්තය ද, ආශ්‍රව ධර්ම තුන වර්ජිත එකුන් පණස් චෛතසිකය ද, අටවිසි රූපය ද, නිර්වාණය ද ලැබෙන්නාහ.": "得到 89 个心、除三个漏法之外的 49 个心所、28 种色与涅槃。",
 "චෛතසික 49 + රූප 28 + නිර්වාණය": "49 个心所＋28 种色＋涅槃",
 "ලෞකික සිත් 81 + චෛතසික 48 + රූප 28": "81 个世间心＋48 个心所＋28 种色",
 "අරමුණු වීම් වශයෙන් ආශ්‍රවයන් සමඟ පවත්නා ධර්ම \"සාසව\" නම් වේ.": "以作为漏之所缘的方式与诸漏一同存在的诸法，称为“有漏”（sāsava）。",
 "ආශ්‍රව සමඟ මිශ්‍ර වූ බව ද ආශ්‍රවයන් හට අරමුණු වූ බව ද ගොදුරු වූ බව එයින් කියැවේ. ලෞකික චිත්ත චෛතසික රූප ධර්ම සියල්ල ම ආශ්‍රව ධර්මයන් හට අරමුණු වන බැවින් \"සාසව\" නම් වෙයි.": "这显示它们与诸漏混合，并且是诸漏的所缘与所依。因为一切世间的心、心所与色法都是漏法的所缘，所以称为“有漏”。",
 "ලෞකික සිත් එක් අසූව ද, තත්සම්ප්‍රයුක්ත චෛතසික දෙපණස ද, අටවිසි රූපය ද ලැබෙන්නාහ.": "得到 81 个世间心、52 个相应心所与 28 种色。",
 "සම්ප්‍රයුක්ත වශයෙන් හෝ අරමුණු කිරීම් වශයෙන් හෝ ආශ්‍රව නොමැති ධර්ම \"අනාසව\" නම් වේ.": "无论是由相应还是由被取为所缘，都没有漏的诸法，称为“无漏”（anāsava）。",
 "න + ආසවා = අනාසවා; \"න\" යන නිපාතයට \"අන්\" ආදේශ වී සන්ධි වූ විට අනාසව පදය සෑදේ.": "na＋āsavā＝anāsavā；当不变词“na”被替换为“an”并作连音（sandhi）时，形成 anāsava 一词。",
