 "ආශ්‍රව ධර්මයන් සමඟ ඒකෝත්පාදාදී වශයෙන් සතර සම්ප්‍රයෝග ලක්ෂණයෙන් මිශ්‍ර වූ ධර්ම \"ආසව සම්පයුත්ත\" නම් වේ.": "以俱生等四种相应特征与诸漏法混合的诸法，称为“漏相应”（āsavasampayutta）。",
 "ලෝභ මූල සිත්වල ඇති ආශ්‍රව ධර්මයන් එකිනෙකාට සම්ප්‍රයුක්ත වන බැවින් \"ආසව සම්පයුත්ත\" වේ.": "因为贪根心中的诸漏法彼此相应，所以是“漏相应”。",
 "ලෝභ මූල 8, දෝස මූල 2, මෝහ මූල 2.": "8 个贪根心、2 个嗔根心、2 个痴根心。",
 "ද්වේෂ මූල මෝහ මූල දෙසිත්හි මෝහය හැර චෛතසික 27.": "两个嗔根心与痴根心中除痴之外的 27 个心所。",
 "අකුසල් සිත් දොළොස ද, ද්වේෂ මූල මෝහ මූල සිත් සතරහි මෝහය වර්ජිත චෛතසික සත්විස්ස ද ලැබෙන්නාහ.": "得到 12 个不善心，以及 4 个嗔根与痴根心中除痴之外的 27 个心所。",
 "අකුසල් සිත් 12 + චෛතසික 26": "12 个不善心＋26 个心所",
 "ආශ්‍රව ධර්මයන් සමඟ මිශ්‍ර නොවූ ධර්ම \"ආසව විප්පයුත්ත\" නම් වේ.": "不与诸漏法混合的诸法，称为“漏不相应”（āsavavippayutta）。",
 "ද්වේෂ මූල සිත් දෙකෙහි සහ මෝහ මූල සිත් දෙකෙහි ඇති මෝහය තනිව පවතින බැවින් \"ආසව විප්පයුත්ත\" වේ.": "因为两个嗔根心与两个痴根心中的痴单独生起，所以是“漏不相应”。",
 "කුසල් 21, විපාක 36, ක්‍රියා 20.": "21 个善心、36 个果报心、20 个唯作心。",
 "තත්සම්ප්‍රයුක්ත චෛතසික 38.": "38 个相应心所。",
 "දෝස මූල මෝහ මූල සිත් සතරෙහි මෝහය.": "四个嗔根与痴根心中的痴。",
 "දොළොස් අකුසල් සිත් වර්ජිත සත්සැත්තෑ චිත්තය ද, තත්සම්ප්‍රයුක්ත චෛතසික අටතිස ද, දෝස මූල මෝහ මූල සිත් සතරෙහි මෝහය ද, අටවිසි රූපය ද, නිර්වාණය ද ලැබෙන්නාහ.": "得到除 12 个不善心之外的 77 个心、38 个相应心所、四个嗔根与痴根心中的痴、28 种色与涅槃。",
 "කුසල් විපාක ක්‍රියා සිත් 77": "77 个善、果报与唯作心",
