 "ආශ්‍රව නම් වූ ද ආශ්‍රවයන් හට අරමුණු නම් වූ ද ධර්ම.": "既称为漏、又是漏之所缘的诸法。",
 "ලෝභ දිට්ඨි මෝහ නම් වූ ආශ්‍රව ධර්ම තිදෙන ලැබෙන්නාහ.": "得到称为贪、见与痴的三个漏法。",
 "ආශ්‍රවයන්හට අරමුණු වන්නා වූ ආශ්‍රව නොවූ ධර්ම.": "是漏之所缘、但本身不是漏的诸法。",
 "ලෞකික සිත් 81, ආශ්‍රව ධර්ම වර්ජිත චෛතසික 49, රූප 28.": "81 个世间心、除漏法之外的 49 个心所、28 种色。",
 "ලෞකික සිත් එක් අසූව ද, ආශ්‍රව ධර්ම වර්ජිත එකුන් පණස් චෛතසිකය ද, අටවිසි රූපය ද ලැබෙන්නාහ.": "得到 81 个世间心、除漏法之外的 49 个心所与 28 种色。",
