 "ලෞකික සිත් 81 + චෛතසික 49 + රූප 28": "81 个世间心＋49 个心所＋28 种色",
 "අනාසවා පදයේ ස්වරූපාර්ථ ලෝකෝත්තර සිත් 8, චෛතසික 36, නිර්වාණය.": "“anāsavā”一词的究竟义：8 个出世间心、36 个心所、涅槃。",
