 "චෛතසික 35 + කර්මජ රූප 20": "35 个心所＋20 种业生色",
 "තෘෂ්ණා දෘෂ්ටීන් විසින් ගන්නා ලද අරමුණක් අනුව, කර්ම ක්ලේශයන් විසින් ස්වකීය ඵලය වශයෙන් ළඟා කොට නො ගන්නා ලද්දා වූ ධර්මයෝ \"අනුපාදින්න\" නම් වේ.": "不以爱与邪见所取的所缘为基础、而被业与烦恼取为自己之果的诸法，称为“非被取”（anupādinna）。",
 "ලෞකික විපාක සිත් වර්ජිත සිත් 57, චෛතසික 52, චිත්තජ රූප 17, උතුජ රූප 15, ආහාරජ රූප 14, නිර්වාණය අනුපාදින්න වේ.": "除世间果报心之外的 57 个心、52 个心所、17 种心生色、15 种时节生色、14 种食生色与涅槃是非被取。",
