 "කෙලෙසුන් සමග ඒකෝත්පාදාදී සතර සම්ප්‍රයෝග ලක්ෂණයෙන් මිශ්‍ර වූ ධර්ම \"කිලෙස සම්පයුත්ත\" නම් වේ.": "以俱生等四种相应特征与烦恼混合的诸法，称为“烦恼相应”（kilesasampayutta）。",
