 "අර්හත් මාර්ගයෙන් නිරවශේෂයෙන් ප්‍රහාණය කටයුතු වූ රූපරාග අරූපරාග මාන උද්ධච්ච අවිජ්ජාවන් සමඟ යෙදුනා වූ දිට්ඨිගත විප්‍රයුක්ත සිත් සතර.": "应被阿罗汉道完全断除的、与色贪（rūparāga）、无色贪（arūparāga）、慢、掉举及无明俱生的四个与邪见不相应的心。",
