 "දිට්ඨිගත සම්ප්‍රයුක්ත සිත් සතරෙහි වූ ලෝභ දිට්ඨි යන උපාදාන ධර්ම 2.": "四个与邪见相应的心中贪与见两个取法。",
 "ලෝභ මූල සිත් 8, ලෝභ දිට්ඨි වර්ජිත චෛතසික සමවිස්ස.": "8 个贪根心、除贪与见的 20 个心所。",
 "ද්වේෂ මූල සිත් 2, මෝහ මූල සිත් 2, ලෞකික කුසල් විපාක ක්‍රියා සිත් 69, ලෝභ දිට්ඨි මාන වර්ජිත චෛතසික 49, දිට්ඨි විප්පයුත්ත සිත්වල ලෝභය, රූප 28.": "2 个嗔根心、2 个痴根心、69 个世间善、果报与唯作心、除贪、见与慢的 49 个心所、与邪见不相应之心中的贪、28 种色。",
 "ලෝභ, ද්වේෂ, මෝහ, මාන, දිට්ඨි, විචිකිච්ඡා, ථීන, උද්ධච්ච, අහිරික, අනොත්තප්ප යන කිලෙස ධර්ම 10.": "10 个烦恼法：贪、嗔、痴、慢、见、疑、昏沉、掉举、无惭、无愧。",
 "පරමාර්ථ ධර්මයන් වශයෙන් ලෝභ, ද්වේෂ, මෝහ, මාන, දිට්ඨි, විචිකිච්ඡා, ථින, උද්ධච්ච, අහිරික, අනොත්තප්ප යන චෛතසිකයන් දසය \"කිලෙස\" නම් වේ.": "就究竟法而言，贪、嗔、痴、慢、见、疑、昏沉、掉举、无惭与无愧十个心所称为“烦恼”（kilesa）。",
