 "සෝවාන් මාර්ගයෙන් ම ප්‍රහාණය වන්නා වූ ධර්මයන් වර්ජිත කොට, අපායගාමී ශක්තියෙන් ද තොර වූ දිට්ඨිගත විප්‍රයුක්ත සිත් 4, දෝස මූල දෙසිත, සෝවාන් මගින් ප්‍රහාණය නොවන උද්ධච්ච සහගත සිත, දිට්ඨි විචිකිච්ඡා වර්ජිත සත්විසි චෛතසිකය, විචිකිච්ඡා සහගත සිතෙහි මෝහය, අවශේෂ සත් සැත්තෑ චිත්තය, අටතිස් චෛතසිකය, රූප 28, නිර්වාණය.": "除预流道本身所断之法外：4 个与邪见不相应、也无导致恶趣之力的心；2 个嗔根心；不为预流道所断的掉举心；除邪见与疑之外的 27 个心所；疑相应心中的痴；其余的 77 个心；38 个心所；28 种色；涅槃。",
 "විචිකිච්ඡා සහගත සිතෙහි මෝහය": "疑相应心中的痴",
 "භාවනාය පහාතබ්බහේතුකා දුකය": "修所断因二法（Bhāvanāya Pahātabbahetukā Duka）",
 "භාවනාය පහාතබ්බහේතුකා ධම්මා - න භාවනාය පහාතබ්බහේතුකා ධම්මාති": "Bhāvanāya pahātabbahetukā dhammā – na bhāvanāya pahātabbahetukā dhammāti",
 "භාවනාය පහාතබ්බහේතුකා ධම්මා": "Bhāvanāya pahātabbahetukā dhammā",
 "සකදාගාමි මාර්ගයෙන් තුනී කිරීම වශයෙන් ප්‍රහාණය කටයුතු වූ ඖදාරික දිට්ඨිගත විප්‍රයුක්ත සිත් 4, ඖදාරික ද්වේෂ මූල දෙසිත, අනාගාමී මාර්ගයෙන් නිරවශේෂව ප්‍රහාණය කටයුතු වූ කාමරාගයෙන් යුක්ත දිට්ඨිගත විප්‍රයුක්ත සිත් 4, ද්වේෂ මූල දෙසිත, අර්හත් මාර්ගයෙන් නිරවශේෂව ප්‍රහාණය කටයුතු වූ රූපරාග අරූපරාග මාන උද්ධච්ච අවිජ්ජාවන් සමඟ යෙදුනා වූ දිට්ඨිගත විප්‍රයුක්ත සිත් 4, උද්ධච්ච සහගත සිත, දිට්ඨි විචිකිච්ඡාවන් හා උද්ධච්ච සිතෙහි මෝහය වර්ජිත පස්විසි චෛතසික.": "应由一来道削弱而断的 4 个与邪见不相应的粗心；2 个粗的嗔根心；应由不还道完全断除的、与欲贪相应而与邪见不相应的 4 个心；2 个嗔根心；应由阿罗汉道完全断除的、与色有爱、无色有爱、慢、掉举及无明相应而与邪见不相应的 4 个心；掉举心；以及除邪见、疑与掉举心中的痴之外的 25 个心所。",
 "භාවනාය පහාතබ්බහෙතුකා": "bhāvanāya pahātabbahetukā",
 "න භාවනාය පහාතබ්බහේතුකා ධම්මා": "Na bhāvanāya pahātabbahetukā dhammā",
 "සෝවාන් මගින් ම ප්‍රහාණය කටයුතු වන දිට්ඨිගත සම්ප්‍රයුක්ත සිත් 4, විචිකිච්ඡා සහගත සිත, සෝවාන් මගින් අනේකාන්තයෙන් ප්‍රහාණය කටයුතු වූ අපායගාමී ශක්තියෙන් යුක්ත දිට්ඨිගත විප්‍රයුක්ත සිත් 4, ද්වේෂ මූල දෙසිත, චෛතසික සත්විස්ස, දොළොස් අකුසල සිත් වර්ජිත අවශේෂ සත්සැත්තෑ චිත්තය, අටතිස් චෛතසිකය, උද්ධච්ච සහගත සිතෙහි මෝහය, රූප 28, නිර්වාණය.": "应仅由预流道断除的 4 个邪见相应心；疑相应心；应由预流道以非专属方式断除的、4 个与邪见不相应而具有导致恶趣之力的心；2 个嗔根心；27 个心所；除 12 个不善心之外其余的 77 个心；38 个心所；掉举心中的痴；28 种色；涅槃。",
 "සවිතක්කා දුකය": "有寻二法（Savitakkā Duka）",
 "සවිතක්කා ධම්මා - අවිතක්කා ධම්මාති": "Savitakkā dhammā – avitakkā dhammāti",
 "සවිතක්කා ධම්මා": "Savitakkā dhammā",
