 "අවිතක්කා ධම්මා": "Avitakkā dhammā",
 "අවිතර්ක සිත් 66, විතර්ක වර්ජිත තත් සම්ප්‍රයුක්ත චෛතසික 37, රූප 28, නිර්වාණය, සවිතර්ක සිත් පස්පණසෙහි විතර්ක පස්පණස.": "66 个无寻心；37 个相应心所（除寻）；28 种色；涅槃；以及 55 个有寻心中的 55 个寻。",
 "සවිචාරා දුකය": "有伺二法（Savicārā Duka）",
 "සවිචාරා ධම්මා - අවිචාරා ධම්මාති": "Savicārā dhammā – avicārā dhammāti",
 "සවිචාරා ධම්මා": "Savicārā dhammā",
 "සවිචාර සිත් සසැට දෙනා, විචාර වර්ජිත චෛතසික එක්පණස.": "66 个有伺（vicāra）心；除伺之外的 51 个心所。",
 "අවිචාරා ධම්මා": "Avicārā dhammā",
 "අවිචාර සිත් පස්පණස, විතර්ක විචාර වර්ජිත චෛතසික සතිස, සවිචාර සිත් සසැටෙහි විචාර චෛතසික සසැට දෙනා, රූප 28, නිර්වාණය.": "55 个无伺心；36 个心所（除寻与伺）；66 个有伺心中的 66 个伺心所；28 种色；涅槃。",
 "සප්පීතිකා දුකය": "有喜二法（Sappītikā Duka）",
