 "අප්පීතිකා ධම්මා": "Appītikā dhammā",
 "අප්‍රීතික සිත් සමසැත්තෑව, තත් සම්ප්‍රයුක්ත එක් පණස් චෛතසිකය, සප්‍රීතික සිත් එක්පණසෙහි ප්‍රීති චෛතසික එක්පණස, අටවිසි රූපය, නිර්වාණ ධාතුව.": "70 个无喜心及其 51 个相应心所；51 个有喜心中的 51 个喜心所；28 种色；涅槃界。",
