 "පීතිසහගතා ධම්මා": "Pītisahagatā dhammā",
 "ප්‍රීති සහගත සිත් එක්පණස, ප්‍රීති දෝස ඉස්සා මච්ඡරිය කුක්කුච්ච විචිකිච්ඡා වර්ජිත චෛතසික සසාළිස.": "51 个喜俱心；46 个心所（除喜、嗔、嫉、悭、恶作、疑）。",
 "\"පීතිසහගත\" යන පදයේ නිරුක්තිය පහත පරිදි විවරණය කළ හැක.": "“pītisahagata”（喜俱）一词的词源，可作如下说明。",
