 "සුඛ සහගතා ධම්මා": "Sukha sahagatā dhammā",
 "සුඛ සහගත සිත් තෙසැට දෙනා, තත් සම්ප්‍රයුක්ත වේදනා දෝස ඉස්සා මච්ඡරිය කුක්කුච්ච විචිකිච්ඡා වර්ජිත චෛතසික සසාළිස.": "63 个乐俱心，以及除受、嗔、嫉、悭、恶作与疑之外的 46 个相应心所。",
